var n=`0780-akoho-sy-voanio`;var t=`world-0780`;var o=`MG`;var a=`eastern-africa`;var r=4;var s=86;var g={en:`Akoho sy Voanio`,ua:`Курка з кокосом`};var h={en:`Akoho sy Voanio is a Madagascar classic prepared with chicken thigh, garlic, ginger root, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка з кокосом, страва кухні країни Мадагаскар зі складниками: куряче стегно, часник, корінь імбиру, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`chicken-thigh`,800,`g`],[`garlic`,4,`clove`],[`ginger-root`,20,`g`],[`lemon-juice`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,210,`g`],[`tomato`,350,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 48 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 48 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:48,i:[[`coconut-milk`,500,`ml`],[`water`,260,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,19,`g`]]}];var m={slug:n,id:t,country:`MG`,region:a,servings:4,minutes:86,title:g,text:h,steps:l};export{o as country,m as default,t as id,s as minutes,a as region,r as servings,n as slug,l as steps,h as text,g as title};